          "Local landmarks are part of the daily map — Downtown Silver Spring on Ellsworth Drive, the AFI Silver Theatre, The Fillmore Silver Spring, NOAA's headquarters at Silver Spring Metro Center and the FDA's White Oak campus. We drop at the correct entrance, not a pin a block away, and we handle the Silver Spring Metro station on the Red Line and the MARC Brunswick Line connections for travelers mixing rail and car."
